using System;
using System.Collections;
using System.Diagnostics;
using System.IO;
using System.Runtime.InteropServices;
using HarmonyLib;
using UnityEngine;
namespace EarlyPlaytest {
// A transparent CPU frame of the original live UIFlashController, never a reconstructed gauge.
public sealed class DashCapture:MonoBehaviour {
 [DllImport("ep6_dash.dll",CallingConvention=CallingConvention.Cdecl,CharSet=CharSet.Unicode)]static extern int EP4_Configure(IntPtr texture,string name);
 [DllImport("ep6_dash.dll",CallingConvention=CallingConvention.Cdecl)]static extern int EP4_Submit(int id,IntPtr header);
 [DllImport("ep6_dash.dll",CallingConvention=CallingConvention.Cdecl)]static extern IntPtr EP4_RenderEvent();
 [DllImport("ep6_dash.dll",CallingConvention=CallingConvention.Cdecl)]static extern int EP4_Error();
 [DllImport("ep6_dash.dll",CallingConvention=CallingConvention.Cdecl)]static extern void EP4_Stop();
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode)]static extern IntPtr LoadLibraryW(string path);
 Camera camera;RenderTexture rt;UIFlashController flash;UIWidget root;Vector3 rootPosition,center;float extent;IntPtr renderEvent;GCHandle pinned;FrameSlot slot;StreamWriter log;long id,observed;bool stopped;float next;
 readonly byte[] packet=new byte[FrameSlot.Size],read=new byte[FrameSlot.Size];
 void Start(){slot=new FrameSlot(@"Local\IceyDCBridge_V1_DASH");pinned=GCHandle.Alloc(packet,GCHandleType.Pinned);log=new StreamWriter(Path.Combine(InputAction.Out,"native_dash.csv"));log.AutoFlush=true;log.WriteLine("utc,frameId,playerFrameId,tickId,generation,charges,capacity,nativeAlpha,readyQpc,zeroAlpha,nonzeroAlpha,hash");StartCoroutine(Capture());}
 IEnumerator Capture(){while(!stopped){yield return new WaitForEndOfFrame();if(stopped||!BridgeArena.Active||Time.realtimeSinceStartup<next)continue;next=Time.realtimeSinceStartup+1f/30f;try{if(!Prepare())continue;Vector3 p=center+flash.transform.position-rootPosition;camera.transform.position=new Vector3(p.x,p.y,camera.transform.position.z);camera.Render();id++;FrameSlot.I(packet,0,0x34504645);FrameSlot.I(packet,4,4);FrameSlot.L(packet,8,id);FrameSlot.L(packet,16,InputAction.Instance.PhysicsTick);FrameSlot.L(packet,24,CpuFrames.LastReadyFrameId);FrameSlot.I(packet,32,WorldMirror.Instance.Generation);FrameSlot.I(packet,36,512);FrameSlot.I(packet,40,128);FrameSlot.I(packet,44,512*128*4);FrameSlot.L(packet,72,Stopwatch.GetTimestamp());FrameSlot.I(packet,96,R.Player.Attribute.currentFlashTimes);FrameSlot.I(packet,100,R.Player.Attribute.flashTimes);FrameSlot.D(packet,112,root==null?0:root.alpha);
 if(EP4_Error()!=0)throw new InvalidOperationException("Dash staging error "+EP4_Error());if(EP4_Submit((int)id,pinned.AddrOfPinnedObject())!=0)GL.IssuePluginEvent(renderEvent,(int)id);
 if(slot.Read(read,observed)){observed=BitConverter.ToInt64(read,8);log.WriteLine(Join(new object[]{DateTime.UtcNow.ToString("o"),observed,BitConverter.ToInt64(read,24),BitConverter.ToInt64(read,16),BitConverter.ToInt32(read,32),BitConverter.ToInt32(read,96),BitConverter.ToInt32(read,100),BitConverter.ToDouble(read,112),BitConverter.ToInt64(read,48),BitConverter.ToInt32(read,272),BitConverter.ToInt32(read,280),BitConverter.ToUInt32(read,180)}));}
 }catch(Exception e){InputAction.Instance.Event("DASH_CAPTURE_FAIL "+e);Dispose();}}}
 bool Prepare(){if(camera!=null)return true;if(R.Ui==null||R.Ui.Flash==null||R.Ui.Camera==null)return false;flash=R.Ui.Flash;root=AccessTools.Field(typeof(UIFlashController),"_widget").GetValue(flash) as UIWidget;var original=R.Ui.Camera.GetComponentInChildren<Camera>();if(original==null)throw new InvalidOperationException("Native dash UI camera absent");Bounds bounds=new Bounds();bool found=false;foreach(UIWidget w in flash.GetComponentsInChildren<UIWidget>(true))foreach(Vector3 p in w.worldCorners){if(!found){bounds=new Bounds(p,Vector3.zero);found=true;}else bounds.Encapsulate(p);}if(!found||bounds.size.x<=0)throw new InvalidOperationException("Native flash widget bounds empty");
 if(LoadLibraryW(Path.Combine(BepInEx.Paths.GameRootPath,"ep6_dash.dll"))==IntPtr.Zero)throw new InvalidOperationException("Dash CPU module unavailable");rootPosition=flash.transform.position;center=bounds.center;var go=new GameObject("BridgeNativeDashWidget");DontDestroyOnLoad(go);camera=go.AddComponent<Camera>();camera.CopyFrom(original);camera.enabled=false;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.clear;camera.rect=new Rect(0,0,1,1);camera.orthographic=true;camera.aspect=4;extent=Mathf.Max(bounds.extents.y*1.3f,bounds.extents.x/4*1.15f);camera.orthographicSize=extent;camera.transform.rotation=original.transform.rotation;camera.transform.position=new Vector3(center.x,center.y,original.transform.position.z);rt=new RenderTexture(512,128,24,RenderTextureFormat.ARGB32);if(!rt.Create())throw new InvalidOperationException("Dash ARGB32 target failed");camera.targetTexture=rt;int result=EP4_Configure(rt.GetNativeTexturePtr(),@"Local\IceyDCBridge_V1_DASH");if(result<0)throw new InvalidOperationException("Dash configure "+result);renderEvent=EP4_RenderEvent();InputAction.Instance.Event("DASH_CAPTURE native UIFlashController live widgets; bounds="+bounds+" alpha="+(root==null?0:root.alpha)+" originalCamera="+original.name+" CPU512x128 30Hz; DC HUD screen bottom center");return true;
 }
 void Dispose(){if(stopped)return;stopped=true;EP4_Stop();if(renderEvent!=IntPtr.Zero)GL.IssuePluginEvent(renderEvent,-1);if(pinned.IsAllocated)pinned.Free();slot?.Dispose();log?.Dispose();if(camera!=null)Destroy(camera.gameObject);if(rt!=null){rt.Release();Destroy(rt);}}
 void OnDestroy(){Dispose();}
 static string Join(object[] values){string[] parts=new string[values.Length];for(int i=0;i<parts.Length;i++)parts[i]=Convert.ToString(values[i],System.Globalization.CultureInfo.InvariantCulture);return string.Join(",",parts);}
}
[HarmonyPatch(typeof(UIFlashController),"OnFlash")]static class NativeDashUsedTrace{[HarmonyPostfix]static void After(int id){InputAction.Instance?.Event("NATIVE_DASH_USED id="+id+" remaining="+R.Player.Attribute.currentFlashTimes+" tick="+InputAction.Instance.PhysicsTick);}}
[HarmonyPatch(typeof(UIFlashController),"OnRecover")]static class NativeDashRecoveredTrace{[HarmonyPostfix]static void After(int id,bool isFilled){InputAction.Instance?.Event("NATIVE_DASH_RECOVER id="+id+" filled="+isFilled+" remaining="+R.Player.Attribute.currentFlashTimes+" tick="+InputAction.Instance.PhysicsTick);}}
[HarmonyPatch(typeof(PlatformMovement),"IgnoreOnOneWayGround")]static class NativeDropTrace{[HarmonyPostfix]static void After(PlatformMovement __instance,bool __result){if(WorldMirror.Instance!=null&&WorldMirror.Instance.Active&&__instance.gameObject==R.Player.gameObject)InputAction.Instance?.Event("NATIVE_DROP result="+__result+" sequence="+InputAction.Instance.Sequence+" generation="+WorldMirror.Instance.Generation+" tick="+InputAction.Instance.PhysicsTick+" oneWayMask="+__instance.m_oneWayLayer.value);}}
}
